// swift-tools-version:5.9
// The iOS simulator XCTest of the olcRTC port's M9 (plan §10.7), run by
// .github/workflows/lab-olc-ffi.yml. build-core.sh fills build/ (the Rust
// core as GhostlaneCoreFFI.xcframework, hev as HevSocks5Tunnel.xcframework)
// and Sources/OlcFfi/ (the UniFFI bindings and their error shim) before any
// build; nothing here is generated by hand.
import PackageDescription

let package = Package(
    name: "OlcFfiLab",
    platforms: [.iOS(.v15), .macOS(.v12)],
    products: [.library(name: "OlcFfi", targets: ["OlcFfi"])],
    targets: [
        .binaryTarget(name: "GhostlaneCoreFFI", path: "build/GhostlaneCoreFFI.xcframework"),
        .binaryTarget(name: "HevSocks5Tunnel", path: "build/HevSocks5Tunnel.xcframework"),
        .target(
            name: "OlcFfi",
            dependencies: ["GhostlaneCoreFFI"],
            path: "Sources/OlcFfi",
            // What a link of the Rust core needs (scripts/build-rust-core-ios.sh's
            // record names the same).
            linkerSettings: [
                .linkedLibrary("c++"),
                .linkedLibrary("resolv"),
                .linkedFramework("Security"),
                .linkedFramework("CoreFoundation"),
                .linkedFramework("SystemConfiguration"),
            ]
        ),
        .testTarget(
            name: "OlcFfiTests",
            dependencies: ["OlcFfi", "HevSocks5Tunnel"],
            path: "Tests/OlcFfiTests"
        ),
    ],
    swiftLanguageVersions: [.v5]
)
